input.command:
mkdir -p test src && cat > test/double.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { double } from '../src/double.mjs';

test('double returns n times 2', () => {
  assert.equal(double(4), 8);
});

test('double of zero is zero', () => {
  assert.equal(double(0), 0);
});

test('double keeps the sign of a negative number', () => {
  assert.equal(double(-3), -6);
});
EOF
node --test test/double.test.mjs 2>&1 | head -20

cat > src/double.mjs <<'EOF'
export function double(n) {
  return n * 2;
}
EOF
node --test test/double.test.mjs 2>&1 | tail -12
